/**
 * deployments.json -> apps/web/lib/deployments.ts
 *
 * Written by scripts/deploy.sh. The generated file is committed so a fresh
 * clone builds without a deploy, and regenerated on every deploy so the two
 * can never drift.
 *
 * One entry per network. A network the contracts have not been deployed to yet
 * still gets an entry — its chain constants are public knowledge and fixed —
 * but with empty ids, which is what `isConfigured` reads to keep the app out
 * of it. That is deliberate: the alternative is a missing key, and `undefined`
 * reaching a contract client is a much worse error than a named refusal.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = new URL('..', import.meta.url).pathname;
const d = JSON.parse(readFileSync(join(root, 'deployments.json'), 'utf8'));

const q = (v) => (v === null || v === undefined ? 'null' : `'${String(v).replace(/'/g, "\\'")}'`);

const entry = (name, n) => `  ${name}: {
    id: '${name}',
    networkPassphrase: ${q(n.networkPassphrase)},
    rpcUrl: ${q(n.rpcUrl)},
    horizonUrl: ${q(n.horizonUrl)},
    /** Testnet only. \`null\` is how the faucet knows it has no meaning here. */
    friendbotUrl: ${q(n.friendbotUrl)},
    /** stellar.expert's path segment: 'testnet' or 'public'. */
    explorerPath: ${q(n.explorerPath)},
    deployedAt: ${q(n.deployedAt)},
    /** Backend hot key: signs settle and refund (and mints, on testnet). */
    resolver: ${q(n.accounts.resolver)},
    /** Where a settled order's USDC ends up. The app never signs for it. */
    treasury: ${q(n.accounts.treasury)},
    escrowId: ${q(n.contracts.escrow.id)},
    usdcId: ${q(n.contracts.usdc.id)},
    /**
     * The issuer of the classic asset this network deposits in.
     *
     * It was \`null\` on testnet for as long as testnet's only USDC was
     * contracts/mock_usdc, a pure SEP-41 Soroban token with no issuer and so
     * no classic payment record to carry a memo. Preview pays for real, so
     * scripts/setup-demo-asset.mjs issued a classic one and both networks now
     * have an issuer, a trustline and the same deposit path.
     *
     * \`usdcId\` still points at the Soroban token. It backs the dormant
     * escrow and is no longer on the deposit rail — the two are separate
     * assets that share a code.
     */
    usdcIssuer: ${q(n.contracts.usdc.issuer)},
    usdcCode: ${q(n.contracts.usdc.symbol)},
    usdcDecimals: ${n.contracts.usdc.decimals},
  },`;

const names = Object.keys(d.networks);

const out = `// GENERATED by scripts/write-deployments-module.mjs — do not edit.
// Source of truth: deployments.json at the repo root, written by
// scripts/deploy.sh. Regenerate with \`./scripts/deploy.sh <network>\`.

export type NetworkId = ${names.map((n) => `'${n}'`).join(' | ')};

export const NETWORK_IDS = [${names.map((n) => `'${n}'`).join(', ')}] as const;

/**
 * Where the app starts, and where it falls back to when anything about the
 * stored or requested network is not understood. It is testnet on purpose:
 * every unknown value must land somewhere that cannot spend real money.
 */
export const DEFAULT_NETWORK: NetworkId = '${d.defaultNetwork}';

export const DEPLOYMENTS = {
${names.map((n) => entry(n, d.networks[n])).join('\n')}
} as const;

export type Deployment = (typeof DEPLOYMENTS)[NetworkId];

/** Narrows an untrusted string — a query param, localStorage — to a network. */
export function asNetwork(value: unknown): NetworkId | null {
  return typeof value === 'string' && (NETWORK_IDS as readonly string[]).includes(value)
    ? (value as NetworkId)
    : null;
}

/** Same, but never fails: anything unrecognised becomes the default. */
export function networkOrDefault(value: unknown): NetworkId {
  return asNetwork(value) ?? DEFAULT_NETWORK;
}

/** True once the contracts and accounts for this network actually exist. */
export function isConfigured(net: NetworkId): boolean {
  const d = DEPLOYMENTS[net];
  return Boolean(d.escrowId && d.usdcId && d.resolver && d.treasury);
}

/**
 * The config, or a refusal naming the network. Called by everything that is
 * about to talk to a chain, so an undeployed network fails here rather than as
 * an unreadable XDR error from a contract client built with an empty id.
 */
export function deployment(net: NetworkId): Deployment {
  if (!isConfigured(net)) {
    throw new Error(\`No hay contratos desplegados en \${net}. Corré ./scripts/deploy.sh \${net}.\`);
  }
  return DEPLOYMENTS[net];
}
`;

writeFileSync(join(root, 'apps/web/lib/deployments.ts'), out);
console.log('  wrote apps/web/lib/deployments.ts');
